import React, { useState } from 'react';
import './index.css'; // Import index.css for the new classes
interface LandingPageProps {
  onSelectView: (view: 'cli' | 'gui') => void;
}

const LandingPage: React.FC<LandingPageProps> = ({ onSelectView }) => {
  const [bio] = useState<string>(
    "I am a Computer Science major at Strathmore University, deeply passionate about cybersecurity, distributed systems, software development, and AI/ML. Outside of academics, I'm an avid sportsman, actively involved in rugby and hitting the gym. My defining characteristic is grit; you could say it's my middle name."
  );

  return (
    <div className="landing-container" style={{ backgroundColor: '#1a1a1a', color: '#d9d9d9', fontFamily: "'Noto Sans', sans-serif", display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: '100vh', padding: '40px', boxSizing: 'border-box' }}>
      <div style={{ display: 'flex', width: '100%', maxWidth: '1200px', gap: '40px' }}>

        {/* Left Column: About Me & Choices */}
        <div style={{ flex: 1, display: 'flex', flexDirection: 'column', justifyContent: 'center' }}>
          <div style={{ marginBottom: '40px' }}>
            <h2 className="large-text highlight" style={{ marginBottom: '15px', fontSize: '2.5em', textAlign: 'left' }}>About Me</h2>
            <p className="info-text" style={{ lineHeight: '1.6', fontSize: '1.1em', textAlign: 'left' }}>{bio}</p>
          </div>
          <div className="choice-container" style={{ display: 'flex', justifyContent: 'flex-start', gap: '20px' }}>
            <div className="landing-box" onClick={() => onSelectView('cli')} style={{ width: '180px', height: '180px', border: '2px solid #007ACC', display: 'flex', flexDirection: 'column', justifyContent: 'center', alignItems: 'center', cursor: 'pointer', transition: 'all 0.3s ease', color: '#d9d9d9' }}>
              <h1 className="bold-text" style={{ fontSize: '2.2em', margin: '0' }}>CLI</h1>
              <p className="small-text" style={{ fontSize: '1em', margin: '10px 0 0 0', textAlign: 'center' }}>Command Line Interface</p>
            </div>
            <div className="landing-box" onClick={() => onSelectView('gui')} style={{ width: '180px', height: '180px', border: '2px solid #007ACC', display: 'flex', flexDirection: 'column', justifyContent: 'center', alignItems: 'center', cursor: 'pointer', transition: 'all 0.3s ease', color: '#d9d9d9' }}>
              <h1 className="bold-text" style={{ fontSize: '2.2em', margin: '0' }}>GUI</h1>
              <p className="small-text" style={{ fontSize: '1em', margin: '10px 0 0 0', textAlign: 'center' }}>Graphical User Interface</p>
            </div>
          </div>
        </div>

        {/* Right Column: Wakatime Charts */}
        <div style={{ flex: 1, display: 'flex', flexDirection: 'column', justifyContent: 'center', alignItems: 'center', gap: '20px' }}>
          <img src="https://wakatime.com/share/@50b41ddf-bd05-4abf-9a01-63eeb1138150/cc39befd-e56e-4db1-ab5f-56922e06766b.svg" alt="Wakatime Languages Used" style={{ width: '100%', height: 'auto' }} />
          <img src="https://wakatime.com/share/@50b41ddf-bd05-4abf-9a01-63eeb1138150/dab37ba9-1c88-4d48-b7db-2e03771b4838.svg" alt="Wakatime Total Time Spent" style={{ width: '100%', height: 'auto' }} />
        </div>

      </div>
    </div>
  );
};

export default LandingPage;
